		and cptr_afectasaldo = #{afectaSaldo}


		and bptr_rapida = #{rapidaFilter}


		and cptr_estadollegada = #{estadoLLegada}

mapper.select:
, proceso_prcp
where cprc_llave = cptr_proceso and cptr_estadopartida is null and cptr_estado = 'A' and cprc_estado = 'A'
